import AppKit
import CraCore
import Foundation
import QuartzCore

/// Floating preview card for Arc Max's 5-Second Previews (fiveSecondPreviews).
/// Appears when hovering over a link on auto-hover sites (Google, DDG, Bing, X, Threads, HN)
/// or when pressing Shift while hovering over any link. Displays a 2-3 bullet point summary
/// generated by the Mac's own Apple Intelligence model without opening the page.
///
/// Designed to match Arc Max's signature two-tone card:
/// - Top header banner: Electric royal blue gradient with favicon squircle, "MAX" doodle, and article title.
/// - Bottom container: Deep midnight navy with a punchy headline verdict and icon-adorned bullet takeaways.
@MainActor
final class LinkSummaryPreviewController {
    static let shared = LinkSummaryPreviewController()

    private var panel: LinkSummaryPanel?
    private var hoverTask: Task<Void, Never>?
    private var dismissTask: Task<Void, Never>?

    private(set) var currentHoveredURL: URL?
    private var currentPageURL: URL?
    private weak var currentWindow: NSWindow?
    private var currentProfilePath: String?
    private weak var currentFavicons: FaviconCache?

    private var flagsMonitor: Any?
    private var clickMonitor: Any?
    private(set) var isPointerInside = false

    /// Fast hover dwell time matching Arc Max (220ms).
    static let autoHoverDelay: TimeInterval = 0.22
    static let shiftHoverDelay: TimeInterval = 0.0
    static let dismissGracePeriod: TimeInterval = 0.25

    private init() {
        // Monitor Shift key changes so pressing Shift while already hovering triggers immediately
        flagsMonitor = NSEvent.addLocalMonitorForEvents(matching: .flagsChanged) { [weak self] event in
            guard let self else { return event }
            if event.modifierFlags.contains(.shift), let url = self.currentHoveredURL, self.panel == nil || self.panel?.isVisible == false {
                self.triggerSummary(url: url, immediate: true)
            }
            return event
        }

        // Dismiss on clicks or keys like Escape
        clickMonitor = NSEvent.addLocalMonitorForEvents(matching: [.leftMouseDown, .rightMouseDown, .keyDown]) { [weak self] event in
            guard let self else { return event }
            if event.type == .keyDown && event.keyCode == 53 { // Escape
                self.dismiss()
                return event
            }
            if self.panel?.isVisible == true, let panel = self.panel {
                let mouse = NSEvent.mouseLocation
                if !panel.frame.contains(mouse) {
                    self.dismiss()
                }
            }
            return event
        }
    }

    /// Called by MainWindowController when the hovered link target changes.
    func linkHoverChanged(
        url: String,
        pageURL: String,
        window: NSWindow?,
        store: SidebarStore,
        profilePath: String?,
        favicons: FaviconCache? = nil
    ) {
        guard store.settings.fiveSecondPreviews, LinkSummaryService.shared.isAvailable else {
            dismiss()
            currentHoveredURL = nil
            return
        }

        if url.isEmpty {
            hoverTask?.cancel()
            hoverTask = nil
            currentHoveredURL = nil
            if !isPointerInside {
                scheduleDismiss()
            }
            return
        }

        guard let targetURL = URL(string: url) else { return }
        let page = URL(string: pageURL)
        guard LinkSummaryPolicy.canSummarize(targetURL: targetURL, pageURL: page) else {
            return
        }

        currentHoveredURL = targetURL
        currentPageURL = page
        currentWindow = window
        currentProfilePath = profilePath
        currentFavicons = favicons
        dismissTask?.cancel()
        dismissTask = nil

        // Speculative background prefetch starts at t=0ms
        LinkSummaryService.shared.prefetch(url: targetURL, profilePath: profilePath)

        let isShift = NSEvent.modifierFlags.contains(.shift)
        let auto = LinkSummaryPolicy.isAutoHoverSite(url: page)

        if auto || isShift {
            triggerSummary(url: targetURL, immediate: isShift)
        }
    }

    private func triggerSummary(url: URL, immediate: Bool) {
        hoverTask?.cancel()
        let delay = immediate ? Self.shiftHoverDelay : Self.autoHoverDelay
        let profile = currentProfilePath
        let window = currentWindow
        let mouseAtStart = NSEvent.mouseLocation
        let favicon = resolveFavicon(for: url)

        hoverTask = Task { @MainActor [weak self] in
            if delay > 0 {
                try? await Task.sleep(for: .seconds(delay))
            }
            guard !Task.isCancelled, let self, self.currentHoveredURL == url else { return }
            guard let window = self.currentWindow ?? window else { return }

            // If result is already in memory cache, present instantly (0ms)
            if let cached = LinkSummaryService.shared.cachedResult(for: url) {
                self.present(result: cached, favicon: favicon, near: mouseAtStart, over: window)
                return
            }

            // Immediately display the Arc Max card with skeleton shimmer so perceived latency is 0ms
            self.presentLoading(url: url, favicon: favicon, near: mouseAtStart, over: window)

            // Await Apple Intelligence summary (HTML prefetch is already completed or nearly done)
            guard let result = await LinkSummaryService.shared.summarize(url: url, profilePath: profile) else {
                if self.currentHoveredURL == url && !self.isPointerInside {
                    self.dismiss()
                }
                return
            }

            guard !Task.isCancelled, self.currentHoveredURL == url || self.isPointerInside else { return }
            self.present(result: result, favicon: favicon, near: mouseAtStart, over: window)
        }
    }

    private func resolveFavicon(for url: URL) -> NSImage? {
        if let favicons = currentFavicons {
            if let img = favicons.image(for: url.absoluteString) { return img }
            if let host = url.host(), let img = favicons.image(forKey: FaviconKey.siteKey(of: host)) { return img }
        }
        return nil
    }

    private func presentLoading(url: URL, favicon: NSImage?, near screenPoint: NSPoint, over parentWindow: NSWindow) {
        dismissTask?.cancel()
        dismissTask = nil

        let p = panel ?? LinkSummaryPanel()
        panel = p
        p.summaryView.configureLoading(url: url, favicon: favicon)

        let size = p.summaryView.calculateSize(isLoading: true)
        let origin = computeOrigin(for: size, near: screenPoint, in: parentWindow)

        p.setFrame(NSRect(origin: origin, size: size), display: true)

        if p.parent == nil {
            parentWindow.addChildWindow(p, ordered: .above)
        }
        p.present()
    }

    private func present(result: LinkSummaryResult, favicon: NSImage?, near screenPoint: NSPoint, over parentWindow: NSWindow) {
        dismissTask?.cancel()
        dismissTask = nil

        let p = panel ?? LinkSummaryPanel()
        panel = p
        p.summaryView.configure(with: result, favicon: favicon)

        let size = p.summaryView.calculateSize(isLoading: false)
        let origin = computeOrigin(for: size, near: screenPoint, in: parentWindow)

        if p.isVisible {
            p.updateFrame(origin: origin, size: size, animated: true)
        } else {
            p.setFrame(NSRect(origin: origin, size: size), display: true)
            if p.parent == nil {
                parentWindow.addChildWindow(p, ordered: .above)
            }
            p.present()
        }
    }

    private func computeOrigin(for size: NSSize, near screenPoint: NSPoint, in parentWindow: NSWindow) -> NSPoint {
        let screen = parentWindow.screen ?? NSScreen.main ?? NSScreen.screens[0]
        let visible = screen.visibleFrame

        var origin = NSPoint(x: screenPoint.x + 12, y: screenPoint.y - size.height - 10)
        if origin.y < visible.minY {
            origin.y = screenPoint.y + 20
        }
        if origin.x + size.width > visible.maxX {
            origin.x = max(visible.minX + 8, visible.maxX - size.width - 12)
        }
        if origin.x < visible.minX {
            origin.x = visible.minX + 8
        }
        return origin
    }

    func pointerEnteredPanel() {
        isPointerInside = true
        dismissTask?.cancel()
        dismissTask = nil
    }

    func pointerLeftPanel() {
        isPointerInside = false
        if currentHoveredURL == nil {
            scheduleDismiss()
        }
    }

    private func scheduleDismiss() {
        dismissTask?.cancel()
        dismissTask = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(Self.dismissGracePeriod))
            guard !Task.isCancelled, let self, !self.isPointerInside, self.currentHoveredURL == nil else { return }
            self.dismiss()
        }
    }

    func dismiss() {
        hoverTask?.cancel()
        hoverTask = nil
        dismissTask?.cancel()
        dismissTask = nil
        currentHoveredURL = nil
        isPointerInside = false
        panel?.dismiss()
    }
}

// MARK: - Panel

final class LinkSummaryPanel: NSPanel {
    let summaryView = LinkSummaryView()

    override var canBecomeKey: Bool { false }
    override var canBecomeMain: Bool { false }

    init() {
        super.init(
            contentRect: NSRect(x: 0, y: 0, width: 330, height: 240),
            styleMask: [.borderless, .nonactivatingPanel],
            backing: .buffered,
            defer: false
        )
        isFloatingPanel = false
        backgroundColor = .clear
        isOpaque = false
        hasShadow = true
        hidesOnDeactivate = false
        isReleasedWhenClosed = false
        animationBehavior = .none
        collectionBehavior = [.fullScreenAuxiliary, .moveToActiveSpace]
        contentView = summaryView
    }

    func present() {
        alphaValue = 0
        orderFront(nil)
        NSAnimationContext.runAnimationGroup { ctx in
            ctx.duration = 0.15
            ctx.timingFunction = CAMediaTimingFunction(name: .easeOut)
            animator().alphaValue = 1
        }
    }

    func updateFrame(origin: NSPoint, size: NSSize, animated: Bool) {
        let targetRect = NSRect(origin: origin, size: size)
        if animated && isVisible {
            NSAnimationContext.runAnimationGroup { ctx in
                ctx.duration = 0.15
                ctx.timingFunction = CAMediaTimingFunction(name: .easeOut)
                animator().setFrame(targetRect, display: true)
            }
        } else {
            setFrame(targetRect, display: true)
        }
    }

    func dismiss() {
        NSAnimationContext.runAnimationGroup({ ctx in
            ctx.duration = 0.12
            animator().alphaValue = 0
        }, completionHandler: { [weak self] in
            MainActor.assumeIsolated {
                guard let self, self.alphaValue == 0 else { return }
                self.parent?.removeChildWindow(self)
                self.orderOut(nil)
            }
        })
    }
}

// MARK: - Arc Max Doodle View

/// The playful Arc Max header doodle: a 4-petal clover icon followed by puffy bubble-letter "MAX".
final class ArcMaxDoodleView: NSView {
    override var isFlipped: Bool { true }

    override func draw(_ dirtyRect: NSRect) {
        super.draw(dirtyRect)

        // 1. Draw 4-lobed clover/flower
        let flowerCenter = NSPoint(x: 10, y: bounds.midY)
        let petalRadius: CGFloat = 3.6
        let dist: CGFloat = 4.2

        let flowerColor = NSColor(red: 0.82, green: 0.88, blue: 1.0, alpha: 0.95)
        flowerColor.setStroke()
        flowerColor.setFill()

        let angles: [CGFloat] = [45, 135, 225, 315]
        for angle in angles {
            let rad = angle * .pi / 180.0
            let cx = flowerCenter.x + cos(rad) * dist
            let cy = flowerCenter.y + sin(rad) * dist
            let path = NSBezierPath(ovalIn: NSRect(x: cx - petalRadius, y: cy - petalRadius, width: petalRadius * 2, height: petalRadius * 2))
            path.lineWidth = 1.0
            path.fill()
            path.stroke()
        }
        let centerDot = NSBezierPath(ovalIn: NSRect(x: flowerCenter.x - 2.2, y: flowerCenter.y - 2.2, width: 4.4, height: 4.4))
        centerDot.fill()

        // 2. Draw "MAX" in bold rounded bubble lettering
        let text = "MAX"
        let baseFont = NSFont.systemFont(ofSize: 18, weight: .black)
        let descriptor = baseFont.fontDescriptor.withDesign(.rounded) ?? baseFont.fontDescriptor
        let roundedFont = NSFont(descriptor: descriptor, size: 18) ?? baseFont

        let attrs: [NSAttributedString.Key: Any] = [
            .font: roundedFont,
            .foregroundColor: NSColor.white,
            .kern: 0.6,
        ]
        let textSize = (text as NSString).size(withAttributes: attrs)
        let textRect = NSRect(x: 23, y: bounds.midY - textSize.height / 2, width: textSize.width, height: textSize.height)
        (text as NSString).draw(in: textRect, withAttributes: attrs)
    }

    override var intrinsicContentSize: NSSize {
        NSSize(width: 66, height: 26)
    }
}

// MARK: - View

final class LinkSummaryView: NSView {
    private let borderLayer = CALayer()

    // 1. Top Header Banner
    private let headerBanner = NSView()
    private let headerGradient = CAGradientLayer()
    private let faviconContainer = NSView()
    private let faviconView = NSImageView()
    private let maxDoodle = ArcMaxDoodleView()
    private let titleLabel = NSTextField(labelWithString: "")

    // 2. Bottom Content Container
    private let contentContainer = NSView()
    private let headlineLabel = NSTextField(wrappingLabelWithString: "")
    private var bulletViews: [NSView] = []
    private var skeletonViews: [NSView] = []
    private var trackingAreaRef: NSTrackingArea?

    override init(frame: NSRect) {
        super.init(frame: frame)
        setup()
    }

    required init?(coder: NSCoder) {
        super.init(coder: coder)
        setup()
    }

    private func setup() {
        wantsLayer = true
        layer?.cornerRadius = 16
        layer?.masksToBounds = true

        CATransaction.begin()
        CATransaction.setDisableActions(true)
        borderLayer.cornerRadius = 16
        borderLayer.borderWidth = 0.5
        borderLayer.borderColor = NSColor.white.withAlphaComponent(0.18).cgColor
        CATransaction.commit()
        layer?.addSublayer(borderLayer)

        // MARK: - Header Banner Setup
        headerBanner.wantsLayer = true
        headerBanner.translatesAutoresizingMaskIntoConstraints = false
        addSubview(headerBanner)

        headerGradient.colors = [
            NSColor(red: 0.25, green: 0.38, blue: 0.98, alpha: 1.0).cgColor,
            NSColor(red: 0.19, green: 0.29, blue: 0.92, alpha: 1.0).cgColor,
        ]
        headerGradient.startPoint = CGPoint(x: 0.5, y: 0)
        headerGradient.endPoint = CGPoint(x: 0.5, y: 1)
        headerBanner.layer?.addSublayer(headerGradient)

        // Favicon Container squircle
        faviconContainer.wantsLayer = true
        faviconContainer.translatesAutoresizingMaskIntoConstraints = false
        CATransaction.begin()
        CATransaction.setDisableActions(true)
        faviconContainer.layer?.cornerRadius = 7.5
        faviconContainer.layer?.masksToBounds = true
        faviconContainer.layer?.backgroundColor = NSColor.white.withAlphaComponent(0.20).cgColor
        faviconContainer.layer?.borderColor = NSColor.white.withAlphaComponent(0.35).cgColor
        faviconContainer.layer?.borderWidth = 0.5
        CATransaction.commit()
        headerBanner.addSubview(faviconContainer)

        faviconView.imageScaling = .scaleProportionallyUpOrDown
        faviconView.translatesAutoresizingMaskIntoConstraints = false
        faviconContainer.addSubview(faviconView)

        // Max Doodle
        maxDoodle.translatesAutoresizingMaskIntoConstraints = false
        headerBanner.addSubview(maxDoodle)

        // Title Label
        titleLabel.font = .systemFont(ofSize: 15.5, weight: .bold)
        titleLabel.textColor = .white
        titleLabel.maximumNumberOfLines = 2
        titleLabel.lineBreakMode = .byWordWrapping
        titleLabel.translatesAutoresizingMaskIntoConstraints = false
        headerBanner.addSubview(titleLabel)

        // MARK: - Content Container Setup
        contentContainer.wantsLayer = true
        contentContainer.translatesAutoresizingMaskIntoConstraints = false
        contentContainer.layer?.backgroundColor = NSColor(red: 0.04, green: 0.06, blue: 0.18, alpha: 1.0).cgColor
        addSubview(contentContainer)

        headlineLabel.font = .systemFont(ofSize: 13, weight: .bold)
        headlineLabel.textColor = .white
        headlineLabel.maximumNumberOfLines = 3
        headlineLabel.lineBreakMode = .byWordWrapping
        headlineLabel.translatesAutoresizingMaskIntoConstraints = false
        contentContainer.addSubview(headlineLabel)

        // Layout Constraints
        NSLayoutConstraint.activate([
            // Header Banner
            headerBanner.leadingAnchor.constraint(equalTo: leadingAnchor),
            headerBanner.trailingAnchor.constraint(equalTo: trailingAnchor),
            headerBanner.topAnchor.constraint(equalTo: topAnchor),

            // Favicon Container
            faviconContainer.leadingAnchor.constraint(equalTo: headerBanner.leadingAnchor, constant: 14),
            faviconContainer.topAnchor.constraint(equalTo: headerBanner.topAnchor, constant: 12),
            faviconContainer.widthAnchor.constraint(equalToConstant: 28),
            faviconContainer.heightAnchor.constraint(equalToConstant: 28),

            faviconView.centerXAnchor.constraint(equalTo: faviconContainer.centerXAnchor),
            faviconView.centerYAnchor.constraint(equalTo: faviconContainer.centerYAnchor),
            faviconView.widthAnchor.constraint(equalToConstant: 18),
            faviconView.heightAnchor.constraint(equalToConstant: 18),

            // Max Doodle
            maxDoodle.trailingAnchor.constraint(equalTo: headerBanner.trailingAnchor, constant: -12),
            maxDoodle.centerYAnchor.constraint(equalTo: faviconContainer.centerYAnchor),
            maxDoodle.widthAnchor.constraint(equalToConstant: 66),
            maxDoodle.heightAnchor.constraint(equalToConstant: 26),

            // Title Label
            titleLabel.leadingAnchor.constraint(equalTo: headerBanner.leadingAnchor, constant: 14),
            titleLabel.trailingAnchor.constraint(equalTo: headerBanner.trailingAnchor, constant: -14),
            titleLabel.topAnchor.constraint(equalTo: faviconContainer.bottomAnchor, constant: 8),
            titleLabel.bottomAnchor.constraint(equalTo: headerBanner.bottomAnchor, constant: -12),

            // Content Container
            contentContainer.topAnchor.constraint(equalTo: headerBanner.bottomAnchor),
            contentContainer.leadingAnchor.constraint(equalTo: leadingAnchor),
            contentContainer.trailingAnchor.constraint(equalTo: trailingAnchor),
            contentContainer.bottomAnchor.constraint(equalTo: bottomAnchor),

            // Headline Label
            headlineLabel.leadingAnchor.constraint(equalTo: contentContainer.leadingAnchor, constant: 14),
            headlineLabel.trailingAnchor.constraint(equalTo: contentContainer.trailingAnchor, constant: -14),
            headlineLabel.topAnchor.constraint(equalTo: contentContainer.topAnchor, constant: 14),
        ])
    }

    override func layout() {
        super.layout()
        borderLayer.frame = bounds
        headerGradient.frame = headerBanner.bounds
    }

    override func updateTrackingAreas() {
        super.updateTrackingAreas()
        if let trackingAreaRef {
            removeTrackingArea(trackingAreaRef)
        }
        let area = NSTrackingArea(rect: bounds, options: [.mouseEnteredAndExited, .activeAlways], owner: self, userInfo: nil)
        addTrackingArea(area)
        trackingAreaRef = area
    }

    override func mouseEntered(with event: NSEvent) {
        LinkSummaryPreviewController.shared.pointerEnteredPanel()
    }

    override func mouseExited(with event: NSEvent) {
        LinkSummaryPreviewController.shared.pointerLeftPanel()
    }

    func configureLoading(url: URL, favicon: NSImage?) {
        let host = LinkSummaryPrompt.host(url)
        titleLabel.stringValue = host.isEmpty ? "Webpage Preview" : host
        setFavicon(favicon)

        headlineLabel.stringValue = ""

        for v in bulletViews { v.removeFromSuperview() }
        bulletViews.removeAll()

        for v in skeletonViews {
            v.layer?.removeAllAnimations()
            v.removeFromSuperview()
        }
        skeletonViews.removeAll()

        // Headline shimmer bar
        let headBar = makeSkeletonBar(width: 250, height: 11)
        contentContainer.addSubview(headBar)
        skeletonViews.append(headBar)

        NSLayoutConstraint.activate([
            headBar.leadingAnchor.constraint(equalTo: contentContainer.leadingAnchor, constant: 14),
            headBar.topAnchor.constraint(equalTo: contentContainer.topAnchor, constant: 14),
            headBar.widthAnchor.constraint(equalToConstant: 250),
            headBar.heightAnchor.constraint(equalToConstant: 11),
        ])

        // 3 bullet shimmer rows
        var lastAnchor = headBar.bottomAnchor
        let widths: [CGFloat] = [230, 260, 190]
        for w in widths {
            let row = makeSkeletonRow(textWidth: w)
            contentContainer.addSubview(row)
            skeletonViews.append(row)

            NSLayoutConstraint.activate([
                row.leadingAnchor.constraint(equalTo: contentContainer.leadingAnchor, constant: 14),
                row.trailingAnchor.constraint(equalTo: contentContainer.trailingAnchor, constant: -14),
                row.topAnchor.constraint(equalTo: lastAnchor, constant: 12),
            ])
            lastAnchor = row.bottomAnchor
        }
    }

    private func makeSkeletonBar(width: CGFloat, height: CGFloat) -> NSView {
        let view = NSView()
        view.wantsLayer = true
        view.translatesAutoresizingMaskIntoConstraints = false
        CATransaction.begin()
        CATransaction.setDisableActions(true)
        view.layer?.cornerRadius = height / 2
        view.layer?.masksToBounds = true
        view.layer?.backgroundColor = NSColor(red: 0.35, green: 0.45, blue: 0.85, alpha: 0.25).cgColor
        CATransaction.commit()

        let pulse = CABasicAnimation(keyPath: "opacity")
        pulse.fromValue = 0.35
        pulse.toValue = 0.80
        pulse.duration = 0.80
        pulse.autoreverses = true
        pulse.repeatCount = .infinity
        pulse.timingFunction = CAMediaTimingFunction(name: .easeInEaseOut)
        view.layer?.add(pulse, forKey: "shimmer")
        return view
    }

    private func makeSkeletonRow(textWidth: CGFloat) -> NSView {
        let row = NSView()
        row.translatesAutoresizingMaskIntoConstraints = false

        let dot = makeSkeletonBar(width: 14, height: 14)
        row.addSubview(dot)

        let line = makeSkeletonBar(width: textWidth, height: 9)
        row.addSubview(line)

        NSLayoutConstraint.activate([
            dot.leadingAnchor.constraint(equalTo: row.leadingAnchor),
            dot.centerYAnchor.constraint(equalTo: row.centerYAnchor),
            dot.widthAnchor.constraint(equalToConstant: 14),
            dot.heightAnchor.constraint(equalToConstant: 14),

            line.leadingAnchor.constraint(equalTo: dot.trailingAnchor, constant: 8),
            line.centerYAnchor.constraint(equalTo: row.centerYAnchor),
            line.widthAnchor.constraint(equalToConstant: textWidth),
            line.heightAnchor.constraint(equalToConstant: 9),
            line.topAnchor.constraint(equalTo: row.topAnchor),
            line.bottomAnchor.constraint(equalTo: row.bottomAnchor),
        ])

        return row
    }

    func configure(with result: LinkSummaryResult, favicon: NSImage?) {
        for v in skeletonViews {
            v.layer?.removeAllAnimations()
            v.removeFromSuperview()
        }
        skeletonViews.removeAll()

        titleLabel.stringValue = result.title.isEmpty ? result.host : result.title
        setFavicon(favicon)

        headlineLabel.stringValue = result.headline ?? "Overview of \(result.host)."

        for v in bulletViews { v.removeFromSuperview() }
        bulletViews.removeAll()

        var lastAnchor = headlineLabel.bottomAnchor
        for (i, bullet) in result.bullets.enumerated() {
            let row = makeBulletRow(text: bullet, index: i)
            contentContainer.addSubview(row)
            bulletViews.append(row)

            NSLayoutConstraint.activate([
                row.leadingAnchor.constraint(equalTo: contentContainer.leadingAnchor, constant: 14),
                row.trailingAnchor.constraint(equalTo: contentContainer.trailingAnchor, constant: -14),
                row.topAnchor.constraint(equalTo: lastAnchor, constant: 10),
            ])
            lastAnchor = row.bottomAnchor
        }
    }

    private func setFavicon(_ img: NSImage?) {
        if let img {
            faviconView.image = img
            faviconView.contentTintColor = nil
        } else {
            let sym = NSImage(systemSymbolName: "globe", accessibilityDescription: nil)
            let config = NSImage.SymbolConfiguration(pointSize: 13, weight: .semibold)
            faviconView.image = sym?.withSymbolConfiguration(config)
            faviconView.contentTintColor = .white
        }
    }

    private static func iconName(for text: String, index: Int) -> String {
        let lower = text.lowercased()
        if lower.contains("ask") || lower.contains("question") || lower.contains("why") || lower.contains("how") {
            return "questionmark.circle"
        }
        if lower.contains("preview") || lower.contains("view") || lower.contains("see") || lower.contains("look") || lower.contains("eye") {
            return "eye"
        }
        if lower.contains("download") || lower.contains("tidy") || lower.contains("tab") || lower.contains("save") || lower.contains("tray") || lower.contains("organize") {
            return "tray.and.arrow.down"
        }
        if lower.contains("chat") || lower.contains("command") || lower.contains("conversation") || lower.contains("message") || lower.contains("discuss") {
            return "bubble.left"
        }
        if lower.contains("ai") || lower.contains("intelligence") || lower.contains("model") || lower.contains("smart") || lower.contains("speed") || lower.contains("fast") {
            return "sparkles"
        }
        let signature = ["questionmark.circle", "eye", "tray.and.arrow.down", "bubble.left", "sparkles"]
        return signature[index % signature.count]
    }

    private func makeBulletRow(text: String, index: Int) -> NSView {
        let row = NSView()
        row.translatesAutoresizingMaskIntoConstraints = false

        let iconName = Self.iconName(for: text, index: index)
        let iconView = NSImageView()
        iconView.translatesAutoresizingMaskIntoConstraints = false
        iconView.imageScaling = .scaleProportionallyDown
        if let sym = NSImage(systemSymbolName: iconName, accessibilityDescription: nil) {
            let config = NSImage.SymbolConfiguration(pointSize: 13, weight: .medium)
            iconView.image = sym.withSymbolConfiguration(config)
            iconView.contentTintColor = NSColor(red: 0.58, green: 0.68, blue: 1.0, alpha: 0.88)
        }
        row.addSubview(iconView)

        let label = NSTextField(wrappingLabelWithString: "")
        label.isEditable = false
        label.isSelectable = false
        label.isBordered = false
        label.drawsBackground = false
        label.maximumNumberOfLines = 3
        label.lineBreakMode = .byWordWrapping
        label.translatesAutoresizingMaskIntoConstraints = false

        // Parse bold prefix before colon and regular explanation after colon
        let cleanText = text.replacingOccurrences(of: "**", with: "")
        let attr = NSMutableAttributedString()
        if let colonIndex = cleanText.firstIndex(of: ":") {
            let key = String(cleanText[...colonIndex])
            let rest = String(cleanText[cleanText.index(after: colonIndex)...])

            let boldAttrs: [NSAttributedString.Key: Any] = [
                .font: NSFont.systemFont(ofSize: 12.5, weight: .bold),
                .foregroundColor: NSColor.white,
            ]
            let regAttrs: [NSAttributedString.Key: Any] = [
                .font: NSFont.systemFont(ofSize: 12.5, weight: .regular),
                .foregroundColor: NSColor(red: 0.84, green: 0.88, blue: 0.96, alpha: 0.95),
            ]
            attr.append(NSAttributedString(string: key, attributes: boldAttrs))
            attr.append(NSAttributedString(string: rest, attributes: regAttrs))
        } else {
            let regAttrs: [NSAttributedString.Key: Any] = [
                .font: NSFont.systemFont(ofSize: 12.5, weight: .medium),
                .foregroundColor: NSColor(red: 0.90, green: 0.93, blue: 1.0, alpha: 0.95),
            ]
            attr.append(NSAttributedString(string: cleanText, attributes: regAttrs))
        }

        let para = NSMutableParagraphStyle()
        para.lineSpacing = 2.0
        attr.addAttribute(.paragraphStyle, value: para, range: NSRange(location: 0, length: attr.length))
        label.attributedStringValue = attr
        row.addSubview(label)

        NSLayoutConstraint.activate([
            iconView.leadingAnchor.constraint(equalTo: row.leadingAnchor),
            iconView.topAnchor.constraint(equalTo: row.topAnchor, constant: 1),
            iconView.widthAnchor.constraint(equalToConstant: 16),
            iconView.heightAnchor.constraint(equalToConstant: 16),

            label.leadingAnchor.constraint(equalTo: iconView.trailingAnchor, constant: 8),
            label.trailingAnchor.constraint(equalTo: row.trailingAnchor),
            label.topAnchor.constraint(equalTo: row.topAnchor),
            label.bottomAnchor.constraint(equalTo: row.bottomAnchor),
        ])

        return row
    }

    func calculateSize(isLoading: Bool = false) -> NSSize {
        let width: CGFloat = 330
        if isLoading {
            return NSSize(width: width, height: 245)
        }
        layoutSubtreeIfNeeded()

        // Header height: top padding (12) + favicon (28) + gap (8) + title + bottom padding (12)
        let headerH = 12 + 28 + 8 + titleLabel.fittingSize.height + 12
        // Content height: top padding (14) + headline + gap (10) + bullet rows + bottom padding (14)
        var contentH = 14 + headlineLabel.fittingSize.height + 10
        for row in bulletViews {
            contentH += row.fittingSize.height + 10
        }
        contentH += 14

        return NSSize(width: width, height: max(220, min(380, headerH + contentH)))
    }
}
